const world=new T.Scene(),models={};for(const id of ['forklift','worker-base','pallet-load','heavy-bay','environment-shell']){const p='frontend/public/models/v3/'+id+'.glb';source_hashes[p]=sha(p);models[id]=await load(path.join(repo,p));}
const vehicle=models.forklift,cargo=models['pallet-load'],support=models['heavy-bay'];world.add(vehicle,cargo,support);
const actor=createWorkerInstance(models['worker-base'],'F01','forklift_driver'),seated=bindSeatedDriver(vehicle,actor,validateSeatedDriverPose(JSON.parse(text('frontend/public/data/v3/seated-driver-pose.json'))));
const joints=Object.fromEntries(['joint__carriage','joint__reach','joint__fork_L','joint__fork_R'].map(n=>[n,vehicle.getObjectByName(n)]));
