function fixedCargo(p,yaw){cargo.position.fromArray(p);cargo.rotation.y=yaw;world.updateMatrixWorld(true);}
function contacts(p,normalRoot,supportRoot,points,kind){const a=flat(triangles(normalRoot),p,-1),b=flat(triangles(supportRoot),p,1);return points.map(point=>{const v=new T.Vector3(...point),x=nearest(v,a),y=nearest(v,b),passed=!!x&&!!y&&x.gap_m<=2e-6&&y.gap_m<=2e-6;return{kind,point_m:point,HU_native:x,support_native:y,passed};});}
const result={source_kind:'visual_fixture',engine_operation:false,operational_admission:false,profile_id:physics.HEAVY_INBOUND_PALLET_PI_PROFILE,endpoints,source_hashes,native_contacts:[],envelopes:[],controls:[],capture:null,scope:['Exact first PALLET455 geometry only; source-adjacent construction retained, no generic pair exemption added.','Fresh route proof uses explicit shallow100 body/cargo component bounds and unchanged .25m padding; original C08 bytes and sourcepacket remain unchanged; contacts remain actual native triangles.']};
