for(const reach of [.4,.2,0]){body(endpoints.stage.engage_position,0,.7,reach);const m=physics.sampleHeavyInboundPalletCapture(capture,joints.joint__reach.matrixWorld);m.decompose(cargo.position,cargo.quaternion,cargo.scale);world.updateMatrixWorld(true);const p=cargo.getWorldPosition(new T.Vector3());result.native_contacts.push(...contacts(.7,cargo,vehicle,[-.4,.4].flatMap(x=>[-.4,0,.4].map(z=>[16+x,.7,p.z+z])),'retraction_fork_support_'+reach));}
for(const [p,yaw]of[[[16,0,12.6],0],[[6,0,18],Math.PI/2],[[120.8,0,17.5],3*Math.PI/2]]){body(p,yaw,.7,0);const m=physics.sampleHeavyInboundPalletCapture(capture,joints.joint__reach.matrixWorld);m.decompose(cargo.position,cargo.quaternion,cargo.scale);world.updateMatrixWorld(true);result.envelopes.push(physics.checkHeavyInboundPalletNativeEnvelope({profile_id:result.profile_id,vehicle,cargo,fork_top_m:.7,extension_m:0,driver:seated.snapshot()}));}
support.position.fromArray(endpoints.target.support_position);support.rotation.y=endpoints.target.support_yaw_rad;body(endpoints.target.engage_position,endpoints.target.vehicle_yaw_rad,.18,.4);const targetMatrix=physics.sampleHeavyInboundPalletCapture(capture,joints.joint__reach.matrixWorld);targetMatrix.decompose(cargo.position,cargo.quaternion,cargo.scale);world.updateMatrixWorld(true);
const targetPoints=[-.53,0,.53].flatMap(x=>[-.4,0,.4].map(z=>new T.Vector3(x,.18,.1+z).applyMatrix4(new T.Matrix4().compose(new T.Vector3(...endpoints.target.support_position),new T.Quaternion().setFromAxisAngle(new T.Vector3(0,1,0),endpoints.target.support_yaw_rad),new T.Vector3(1,1,1))).toArray()));result.native_contacts.push(...contacts(.18,cargo,support,targetPoints,'target_pi_HU_M03'));
result.target_capture={actual_position:cargo.position.toArray(),expected_position:endpoints.target.HU_position,maximum_position_error_m:cargo.position.distanceTo(new T.Vector3(...endpoints.target.HU_position)),quaternion:cargo.quaternion.toArray()};
assert.throws(()=>physics.captureHeavyInboundPallet(joints.joint__reach.matrixWorld,cargo.matrixWorld,'old-relative0'),/EXPLICIT_PALLET_PI_PROFILE_REQUIRED/);result.controls.push('old_profile_not_silently_selected');
const shifted=cargo.matrixWorld.clone();shifted.elements[14]+=.01;assert.throws(()=>physics.captureHeavyInboundPallet(joints.joint__reach.matrixWorld,shifted,result.profile_id),/OFFSET_MISMATCH/);result.controls.push('capture_offset_mutation_refused');
const router=createWarehouseRouter(bundle,policy),request={source_kind:'visual_fixture',engine_operation:false,mode:'forklift',actor_id:'F01',vehicle_id:'FL01',cargo_archetype_id:'PALLET_LOAD',from_node_id:'v3:service:IN_W_BULK',to_node_id:endpoints.target.graph_node_id,service_port_id:null,closed_arc_ids:[]};
const route=router.route(request);assert(route.ok);const preview=compileVehicleRoutePreview(bundle,route),arcs=route.arc_ids.map(id=>bundle.layout.vehicle.arcs.find(a=>a.arc_id===id));
const routeData={source_kind:'visual_fixture',engine_operation:false,route,preview_duration_s:preview.duration_s,preview_phases:preview.phases,source_arcs:arcs.map(a=>({arc_id:a.arc_id,from_node_id:bundle.layout.vehicle.nodes[a.from_node_index].node_id,to_node_id:bundle.layout.vehicle.nodes[a.to_node_index].node_id,length_m:a.length_m,geometry:a.fields.geometry,motion_direction:a.fields.motion_direction,allowed_cargo_archetype_ids:a.fields.allowed_cargo_archetype_ids,from:sampleVehicleArc(a,0),to:sampleVehicleArc(a,1)}))};
fs.writeFileSync(path.join(own,'source-route.json'),JSON.stringify(routeData,null,2)+'\n');
fs.writeFileSync(path.join(own,'endpoint-tables.json'),JSON.stringify(endpoints,null,2)+'\n');
// Affected handling only. At each interval yaw is constant and every control is
// affine between endpoints; swept native component AABBs therefore enclose the
// complete interval. This adds no whole-bone/whole-mesh collision exemption.
const gap=(a,b)=>Math.max(b.min.x-a.max.x,a.min.x-b.max.x,b.min.y-a.max.y,a.min.y-b.max.y,b.min.z-a.max.z,a.min.z-b.max.z);
function componentBoxes(root,relative){const rows=triangles(root);if(relative)for(const r of rows)for(const v of[r.tri.a,r.tri.b,r.tri.c])v.applyMatrix4(relative);return native.components(rows).map(p=>({id:p.node+'#'+p.component,box:p.bounds,triangles:p.rows.map(r=>r.tri)}));}
function union(a,b){assert.equal(a.length,b.length);return a.map((p,i)=>{assert.equal(p.id,b[i].id);return{id:p.id,box:p.box.clone().union(b[i].box),triangles:p.triangles,other_triangles:b[i].triangles};});}
const {describeNativeJointSolid,separateNativeJointSolids}=await import(pathToFileURL(path.join(repo,'frontend/tools/native-convex-joint-v3.mjs')));
// Positive separation per actual boundary triangle handles the source concave
// L-forks without replacing them by their intersecting convex hull. Every solid
// descriptor must first pass independent closure/orientation checks.
function triangleSweepsSeparate(a,b){
 const simple=(a,b)=>{try{describeNativeJointSolid(a.triangles);}catch{return false;}
  const point=b.box.getCenter(new T.Vector3());let winding=0;for(const t of a.triangles){const x=t.a.clone().sub(point),y=t.b.clone().sub(point),z=t.c.clone().sub(point),lx=x.length(),ly=y.length(),lz=z.length();winding+=2*Math.atan2(x.dot(y.clone().cross(z)),lx*ly*lz+x.dot(y)*lz+y.dot(z)*lx+z.dot(x)*ly);}if(Math.abs(winding)>2*Math.PI)return false;
  return a.triangles.every((t,i)=>{const box=new T.Box3().setFromPoints([t.a,t.b,t.c]);const u=a.other_triangles?.[i];if(u)box.expandByPoint(u.a).expandByPoint(u.b).expandByPoint(u.c);return gap(box,b.box)>=-2e-6;});};
 return simple(a,b)||simple(b,a);
}
const handling=[];
for(const site of['stage','target']){
 const e=endpoints[site],origin=e.support_position,yaw=e.support_yaw_rad,vYaw=e.vehicle_yaw_rad,eng=e.engage_position,safe=e.prepared_position;
 support.position.fromArray(origin);support.rotation.y=yaw;
 const steps=site==='stage'?[{id:'extend_empty',a:[safe,.7,0],b:[safe,.7,.4],attached:false},{id:'lower_empty',a:[safe,.7,.4],b:[safe,.18,.4],attached:false},{id:'insert_empty',a:[safe,.18,.4],b:[eng,.18,.4],attached:false},{id:'lift',a:[eng,.18,.4],b:[eng,.7,.4],attached:true},{id:'retract_loaded',a:[eng,.7,.4],b:[eng,.7,0],attached:true},{id:'depart_initial_straight',a:[eng,.7,0],b:[[16,0,10.808290376865476],.7,0],attached:true}]:[{id:'approach_loaded',a:[safe,.7,0],b:[eng,.7,0],attached:true},{id:'extend_loaded',a:[eng,.7,0],b:[eng,.7,.4],attached:true},{id:'setdown',a:[eng,.7,.4],b:[eng,.18,.4],attached:true},{id:'withdraw_empty',a:[eng,.18,.4],b:[safe,.18,.4],attached:false},{id:'raise_empty',a:[safe,.18,.4],b:[safe,.7,.4],attached:false},{id:'retract_empty',a:[safe,.7,.4],b:[safe,.7,0],attached:false}];
 for(const step of steps){
  const take=c=>{body(c[0],vYaw,c[1],c[2]);if(step.attached){const m=physics.sampleHeavyInboundPalletCapture(capture,joints.joint__reach.matrixWorld);m.decompose(cargo.position,cargo.quaternion,cargo.scale);}else fixedCargo(e.HU_position,e.HU_yaw_rad);world.updateMatrixWorld(true);const inverse=cargo.matrixWorld.clone().invert();return{vehicle:componentBoxes(vehicle),cargo:componentBoxes(cargo),support:componentBoxes(support),vehicleRelative:componentBoxes(vehicle,inverse),cargoRelative:componentBoxes(cargo,inverse)};};
  const a=take(step.a),b=take(step.b),pairs=[['vehicle_M03',union(a.vehicle,b.vehicle),a.support],['HU_M03',union(a.cargo,b.cargo),a.support],['vehicle_HU',union(a.vehicleRelative,b.vehicleRelative),union(a.cargoRelative,b.cargoRelative)]];
  const failures=[],kindGaps={};let pairCount=0,minimumGap=Infinity,triangleCertified=0;for(const[kind,left,right]of pairs)for(const x of left)for(const y of right){const d=gap(x.box,y.box);pairCount++;minimumGap=Math.min(minimumGap,d);kindGaps[kind]=Math.min(kindGaps[kind]??Infinity,d);if(d< -2e-6){if(triangleSweepsSeparate(x,y))triangleCertified++;else failures.push({kind,a:x.id,b:y.id,aabb_overlap_m:-d});}}
  handling.push({site,phase:step.id,passed:failures.length===0,pair_count:pairCount,minimum_support_axis_gap_m:minimumGap,per_kind_minimum_aabb_support_gap_m:kindGaps,triangle_sweep_certificates:triangleCertified,unseparated_native_component_sweeps:failures.slice(0,8),failure_count:failures.length,method:'Native component endpoint swept AABBs; unresolved concave pairs use closed-oriented boundary-triangle swept AABBs against other solid bounds, in cargo frame for co-motion. Constant-yaw affine controls only. Closed boundary separated from the entire convex other bound plus an exterior-winding centre witness excludes containment; continuous triangle sweeps prevent a later entry. Negative result is inconclusive, not penetration.'});
 }
}
result.handling_clearance=handling;
result.endpoint_contacts_envelopes_passed=result.native_contacts.every(c=>c.passed)&&result.envelopes.every(e=>e.passed)&&result.target_capture.maximum_position_error_m<=2e-6;
result.passed=result.native_contacts.every(c=>c.passed)&&result.envelopes.every(e=>e.passed)&&result.target_capture.maximum_position_error_m<=2e-6&&handling.every(r=>r.passed);
for(const[p,h]of Object.entries(source_hashes))assert.equal(sha(p),h,'Source drift '+p);
fs.writeFileSync(path.join(own,'checks.json'),JSON.stringify(result,null,2)+'\n');
seated.release();disposeWorkerInstance(actor);for(const root of Object.values(models))root.traverse(n=>{n.geometry?.dispose();for(const m of n.material?(Array.isArray(n.material)?n.material:[n.material]):[])m.dispose();});
console.log(JSON.stringify({passed:result.passed,native_contacts:result.native_contacts.length,handling:handling.map(r=>({site:r.site,phase:r.phase,passed:r.passed,pairs:r.pair_count,unresolved:r.failure_count,witness:r.unseparated_native_component_sweeps.slice(0,1)})),envelopes:result.envelopes.map(e=>({passed:e.passed,body:e.body.maximum_nominal_bounds_excess_m,cargo:e.cargo.maximum_nominal_bounds_excess_m,driver:e.driver_contacts_passed})),route:{arcs:arcs.length,length_m:route.length_m,duration_s:preview.duration_s},target:result.target_capture},null,2));

import * as T from '../../../frontend/node_modules/three/build/three.module.js';
import {GLTFLoader} from '../../../frontend/node_modules/three/examples/jsm/loaders/GLTFLoader.js';
import {readFile} from 'node:fs/promises';
export {T};
export async function load(file){const b=await readFile(file);return(await new GLTFLoader().parseAsync(b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength),'')).scene;}
export function triangles(root){root.updateMatrixWorld(true);const out=[];root.traverse(n=>{if(!n.isMesh)return;const p=n.geometry.getAttribute('position'),ix=n.geometry.index;for(let i=0;i<(ix?.count??p.count);i+=3){const t=new T.Triangle(...[0,1,2].map(k=>new T.Vector3().fromBufferAttribute(p,ix?ix.getX(i+k):i+k).applyMatrix4(n.matrixWorld)));out.push({node:n.name,triangle:i/3,tri:t,normal:t.getNormal(new T.Vector3()),source_parts:JSON.parse(n.userData.source_parts_json??'[]')});}});return out;}
export function flat(tris,y,up,eps=2e-6){return tris.filter(t=>t.normal.y*up>.99999&&[t.tri.a,t.tri.b,t.tri.c].every(v=>Math.abs(v.y-y)<=eps));}
export function nearest(p,tris){let best=null;for(const r of tris){const point=r.tri.closestPointToPoint(p,new T.Vector3()),distance=point.distanceTo(p);if(!best||distance<best.gap_m)best={node:r.node,triangle:r.triangle,point_m:point.toArray(),normal:r.normal.toArray(),gap_m:distance,source_parts:r.source_parts};}return best;}
export function bounds(tris){return new T.Box3().setFromPoints(tris.flatMap(t=>[t.tri.a,t.tri.b,t.tri.c]));}
export function components(tris){const groups=new Map();for(const r of tris){const a=groups.get(r.node)??[];a.push(r);groups.set(r.node,a);}const out=[];for(const[node,rows]of groups){const parent=rows.map((_,i)=>i),owners=new Map(),find=i=>parent[i]===i?i:parent[i]=find(parent[i]);for(let i=0;i<rows.length;i++)for(const v of[rows[i].tri.a,rows[i].tri.b,rows[i].tri.c]){const k=v.toArray().map(x=>Math.round(x*1e9)).join(',');if(owners.has(k))parent[find(i)]=find(owners.get(k));else owners.set(k,i);}const parts=new Map();for(let i=0;i<rows.length;i++){const k=find(i),a=parts.get(k)??[];a.push(rows[i]);parts.set(k,a);}let index=0;for(const part of parts.values())out.push({node,component:index++,triangles:part.map(r=>r.triangle),bounds:bounds(part),rows:part});}return out;}
export function axisSeparation(a,b){const list=[];for(const axis of['x','y','z']){const d1=b.min[axis]-a.max[axis],d2=a.min[axis]-b.max[axis];if(d1>=0)list.push({axis,gap_m:d1,side:'A_below_B'});if(d2>=0)list.push({axis,gap_m:d2,side:'B_below_A'});}return list.sort((a,b)=>b.gap_m-a.gap_m);}
function clip(poly,a,b){const side=p=>(b.x-a.x)*(p.y-a.y)-(b.y-a.y)*(p.x-a.x),out=[];for(let i=0;i<poly.length;i++){const p=poly[i],q=poly[(i+1)%poly.length],u=side(p),v=side(q);if(u>=-1e-12)out.push(p);if((u>=-1e-12)!==(v>=-1e-12))out.push(p.clone().lerp(q,u/(u-v)));}return out;}
export function overlapXZ(a,b){const p=t=>[t.a,t.b,t.c].map(v=>new T.Vector2(v.x,v.z)),area=v=>v.reduce((s,u,i)=>{const w=v[(i+1)%v.length];return s+u.x*w.y-w.x*u.y;},0)/2;let poly=p(a),boundary=p(b);if(area(boundary)<0)boundary.reverse();for(let i=0;i<3&&poly.length;i++)poly=clip(poly,boundary[i],boundary[(i+1)%3]);return Math.abs(area(poly));}
export function boxJSON(b){return{min:b.min.toArray(),max:b.max.toArray()};}

/** Independent native-solid support separation. No hierarchy/adjacency exceptions. */
import assert from 'node:assert/strict';
import * as T from 'three';

const vertexKey=v=>v.toArray().map(x=>x.toFixed(9)).join(',');
const unique=points=>[...new Map(points.map(p=>[vertexKey(p),p])).values()];
const V=()=>new T.Vector3();

/** Input triangles must describe one actual closed, outward-oriented component. */
export function describeNativeJointSolid(triangles,{tolerance=1e-7,requireConvex=false}={}){
 assert(triangles.length>=4,'Closed solid triangles required');
 const vertices=unique(triangles.flatMap(t=>[t.a,t.b,t.c]));
 assert(vertices.every(p=>p.toArray().every(Number.isFinite)),'Finite native vertices required');
 const origin=vertices.reduce((a,p)=>a.add(p),V()).divideScalar(vertices.length);
 const edges=new Map(),planes=[],directions=[];let signedVolume=0;
 for(const t of triangles){
  assert(t.getArea()>1e-13,'Noncollapsed native triangles required');
  const points=[t.a,t.b,t.c],normal=t.getNormal(V()),constant=normal.dot(t.a);
  if(!planes.some(p=>p.normal.distanceTo(normal)<1e-7&&Math.abs(p.constant-constant)<tolerance))planes.push({normal,constant});
  signedVolume+=t.a.clone().sub(origin).dot(t.b.clone().sub(origin).cross(t.c.clone().sub(origin)))/6;
  for(let i=0;i<3;i++){
   const a=vertexKey(points[i]),b=vertexKey(points[(i+1)%3]),key=[a,b].sort().join('|'),edge=edges.get(key)??{count:0,orientation:0};
   assert(a!==b,'Distinct native triangle vertices required');edge.count++;edge.orientation+=a<b?1:-1;edges.set(key,edge);
   const d=points[(i+1)%3].clone().sub(points[i]).normalize();
   if(!directions.some(x=>Math.abs(x.dot(d))>1-1e-10))directions.push(d);
  }
 }
 assert([...edges.values()].every(e=>e.count===2&&e.orientation===0),'Closed consistently oriented native component required');
 const maximumConvexityViolation=Math.max(...planes.flatMap(p=>vertices.map(v=>p.normal.dot(v)-p.constant)));
 if(requireConvex)assert(maximumConvexityViolation<=tolerance,'Actual component must be convex for complete SAT classification');
 assert(signedVolume>1e-12,'Positive native closed-solid volume required');
 return {vertices,planes,directions,signed_volume_m3:signedVolume,convex:maximumConvexityViolation<=tolerance,maximum_convexity_violation_m:maximumConvexityViolation,triangle_count:triangles.length};
}

export function describeConvexNativeSolid(triangles,options={}){return describeNativeJointSolid(triangles,{...options,requireConvex:true});}

/** All face normals plus all edge cross products: the complete convex SAT axes. */
export function separateNativeJointSolids(a,b,{tolerance=2e-6}={}){
 const axes=[];const add=n=>{if(n.lengthSq()<1e-18)return;const axis=n.clone().normalize();if(!axes.some(x=>Math.abs(x.dot(axis))>1-1e-10))axes.push(axis);};
 for(const p of [...a.planes,...b.planes])add(p.normal);
 for(const u of a.directions)for(const v of b.directions)add(u.clone().cross(v));
 let gap=-Infinity,axis=null,intervals=null;
 for(const n of axes){
  const av=a.vertices.map(p=>n.dot(p)),bv=b.vertices.map(p=>n.dot(p));
  const ai=[Math.min(...av),Math.max(...av)],bi=[Math.min(...bv),Math.max(...bv)];
  const current=Math.max(bi[0]-ai[1],ai[0]-bi[1]);
  if(current>gap){gap=current;axis=n.toArray();intervals=[ai,bi];}
 }
 return {separated_within_native_tolerance:gap>=-tolerance,strictly_separated:gap>0,
  maximum_separating_projection_gap_m:gap,axis_world:axis,projection_intervals_m:intervals,
  axes_tested:axes.length,tolerance_m:tolerance,both_components_convex:a.convex&&b.convex,
  interpretation:'A positive separating support gap bounds every actual native triangle even for concave components; no convex-hull replacement is made. A negative result is inconclusive for concave components and is never penetration depth or Euclidean clearance. Native tolerance applies only at a coincident fitted seam; no bone-name exception.'};
}

export function separateConvexNativeSolids(a,b,options={}){assert(a.convex&&b.convex,'Both actual native components must be convex for complete SAT classification');return separateNativeJointSolids(a,b,options);}
